// Order defines model for Order.
type Order struct {
	BranchId     openapi_types.UUID        `json:"branch_id"`
	CreatedAt    time.Time                 `json:"created_at"`
	Fulfillments []Fulfillment             `json:"fulfillments"`
	Id           openapi_types.UUID        `json:"id"`
	Lines        []OrderLine               `json:"lines"`
	Notes        nullable.Nullable[string] `json:"notes,omitempty"`

	// OrderNo Examples: AE-2K7F4M
	OrderNo string `json:"order_no"`

	// Quote Price is a state machine, not a column:
	// `estimated → authorized → adjusted → captured → refunded`.
	// Laundry priced by weight is `adjusted` after pickup — the model must carry that
	// natively rather than treating it as an exception.
	Quote  PriceQuote  `json:"quote"`
	Status OrderStatus `json:"status"`
	Vendor *Vendor     `json:"vendor,omitempty"`
}

// OrderStatus defines model for Order.Status.
type OrderStatus string

// OrderInput defines model for OrderInput.
type OrderInput struct {
	AddressId openapi_types.UUID `json:"address_id"`
	BranchId  openapi_types.UUID `json:"branch_id"`
	Lines     []struct {
		OfferingId openapi_types.UUID `json:"offering_id"`

		// Options Vertical-specific selections, validated by the service type's strategy.
		Options  *map[string]interface{} `json:"options,omitempty"`
		Quantity int                     `json:"quantity"`
	} `json:"lines"`
	Notes *string `json:"notes,omitempty"`

	// Schedule One entry per fulfillment the vertical requires. A laundry order supplies
	// two (pickup and delivery); a single-visit service supplies one. The count
	// is validated against the service type's fulfillment pattern.
	Schedule struct {
		Slots []struct {
			Date     openapi_types.Date          `json:"date"`
			Kind     OrderInputScheduleSlotsKind `json:"kind"`
			WindowId openapi_types.UUID          `json:"window_id"`
		} `json:"slots"`
	} `json:"schedule"`

	// Source Attribution. Present when the order originated from a reel — this is the
	// conversion signal Phase 3 depends on, so the field exists from Phase 1
	// even though nothing writes it yet.
	Source *struct {
		ActionId nullable.Nullable[openapi_types.UUID] `json:"action_id,omitempty"`
		ReelId   nullable.Nullable[openapi_types.UUID] `json:"reel_id,omitempty"`
	} `json:"source,omitempty"`
}

// OrderInputScheduleSlotsKind defines model for OrderInput.Schedule.Slots.Kind.
type OrderInputScheduleSlotsKind string

// OrderLine Name and price are **snapshots** taken when the order was placed. Never render
// from the offering — a vendor's later price change must not rewrite history.
